// Uploads are served by the /media route, whichever storage holds the files.
export const MEDIA_PATH = '/media/'

export const mediaUrl = (filename: string) => `${MEDIA_PATH}${filename}`

/** Name of the small preview generated next to every upload. Always WebP. */
export const thumbnailFilename = (filename: string) => `${filename.replace(/\.[^.]+$/, '')}.thumb.webp`

/** Filenames are generated by the server (random id + extension); anything else is rejected. */
export const SAFE_FILENAME = /^[a-z0-9][a-z0-9-]*(\.thumb)?\.(jpg|png|webp|gif)$/

// Emails: some clients (classic Outlook, older Apple Mail and Android) cannot show WebP, so emails
// link a WebP upload as /media/email/<name>.png, a lossless PNG made from it on first request and
// kept in storage as <name>.email.png (removed with the upload).
export const EMAIL_IMAGE_PATH = '/media/email/'
export const emailImageFilename = (filename: string) => `${filename.replace(/\.[^.]+$/, '')}.email.png`
/** An email image address: the upload's random name with .png. */
export const SAFE_EMAIL_IMAGE = /^[a-z0-9][a-z0-9-]*\.png$/
/** Every key storage holds: uploads and their thumbnails (SAFE_FILENAME), and the email copies. */
export const SAFE_STORAGE_KEY = /^[a-z0-9][a-z0-9-]*((\.thumb)?\.(jpg|png|webp|gif)|\.email\.png)$/
